for line in open('region.fasta'):
    if line.startswith('>'):continue
    seq+=line.strip()
rc=seq.translate(str.maketrans('ACGT','TGCA'))[::-1]
code = {}
bases='TCAG'
aas='FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'
i=0
for a in bases:
    for b in bases:
        for c in bases:
            code[a+b+c]=aas[i]; i+=1
def tr(s): return ''.join(code[s[i:i+3]] for i in range(0,len(s)-2,3))

# ORFs
def find_orf(s, start, strand):
    # given start index of ATG, extend
    j=start
    while j+3<=len(s):
        if code[s[j:j+3]]=='*': break
        j+=3
    return j

def allorfs(s,strand):
    res=[];n=len(s)
    for f in range(3):
        i=f;laststop=f-3
        while i+3<=n:
            if code[s[i:i+3]]=='*': laststop=i
            if s[i:i+3]=='ATG':
                e=find_orf(s,i,strand)
                res.append((strand,f,i,e,(e-i)//3))
            i+=3
    return res

